const config = {
    // Choose "direct" (ESP8266 UDP) or "remote" (Pi bridge or Hamlib rotctld TCP).
    connectionType: "direct",
    remoteHost: "192.168.0.35",
    remotePort: 4533,
    host: "192.168.0.36",   // CHANGE THIS
    commandPort: 4210,
    localReplyPort: 4211,
    query: "GET_BEARING",
    stop: "<PST><STOP>",
    setPrefix: "<AZIMUTH>",
    calibrate: "CAL_DECL",
    qrzUsername: "Call",
    qrzPassword: "Password",
    stationLat: 41.12345,
    stationLon: -73.12345
};
if (config.connectionType === "pi") config.connectionType = "remote";
flow.set("rotatorConfig", config);
flow.set("rotatorProtocol", config.connectionType === "direct" ? "direct" : null);

const state = {
    online: false,
    bearing: null,
    target: null,
    direction: "STOP",
    stuck: false,
    error: "",
    lastReply: "",
    lastCommand: "",
    lastSeen: 0
};
flow.set("rotatorState", state);
node.status({fill:"green",shape:"dot",text:config.connectionType});
return {payload:state};

const cfg = flow.get("rotatorConfig");
if (!cfg) return null;
return {
    payload: Buffer.from(cfg.query),
    ip: cfg.host,
    port: cfg.commandPort
};

let state = flow.get("rotatorState") || {};
const wasOnline = !!state.online;
state.online = !!state.lastSeen && (Date.now() - state.lastSeen < 6500);
if (!state.online) state.direction = "STOP";
flow.set("rotatorState", state);
if (wasOnline !== state.online || !state.online) return {payload:state};
return null;

const cfg = flow.get("rotatorConfig");
if (!cfg || msg.topic === "rotator-command-status") return null;
const mode = cfg.connectionType;
const command = msg.payload && typeof msg.payload === "object" && !Buffer.isBuffer(msg.payload) ? cfg.query : String(msg.payload ?? "").trim();
if (![cfg.query, cfg.stop, cfg.calibrate].includes(command) &&
    !/^<AZIMUTH>\d{1,3}$/.test(command)) return null;

function markOffline() {
    const state = flow.get("rotatorState") || {};
    delete state.pendingTarget;
    state.routingViaNorth = false;
    state.online = false;
    state.lastSeen = 0;
    if (mode === "remote") flow.set("rotatorProtocol", null);
    flow.set("rotatorState", state);
}
function receive(line) {
    node.send({payload:line});
}

if (!globalThis.rotatorLink) {
    const link = {ready:false, buffer:"", close(){}};
    if (mode === "direct") {
        if (net.isIP(cfg.host) !== 4 || ![cfg.commandPort, cfg.localReplyPort].every(port => Number.isInteger(port) && port >= 1 && port <= 65535)) {
            node.error("Direct mode requires an ESP8266 IPv4 address and valid UDP ports.");
            return null;
        }
        const socket = dgram.createSocket("udp4");
        link.close = () => { try { socket.close(); } catch {} };
        link.send = value => socket.send(Buffer.from(value), Number(cfg.commandPort), cfg.host);
        socket.on("error", error => {
            node.status({fill:"red",shape:"ring",text:error.message});
            if (!link.ready) link.close();
        });
        socket.on("close", () => {
            if (globalThis.rotatorLink === link) {
                globalThis.rotatorLink = null;
                markOffline();
            }
        });
        socket.on("message", (data, peer) => {
            if (peer.address === cfg.host && peer.port === Number(cfg.commandPort)) receive(String(data));
        });
        globalThis.rotatorLink = link;
        socket.bind(Number(cfg.localReplyPort), () => {
            link.ready = true;
            node.status({fill:"green",shape:"dot",text:"Direct UDP"});
            link.send(cfg.query);
        });
    } else if (mode === "remote") {
        if (!String(cfg.remoteHost || "").trim() || !Number.isInteger(Number(cfg.remotePort)) ||
            Number(cfg.remotePort) < 1 || Number(cfg.remotePort) > 65535) {
            node.error("Set a remote hostname and TCP port from 1 to 65535 in CONFIG.");
            return null;
        }
        const socket = net.createConnection({host:cfg.remoteHost, port:Number(cfg.remotePort)});
        globalThis.rotatorLink = link;
        link.close = () => { clearTimeout(link.probe); socket.destroy(); };
        socket.setEncoding("utf8");
        socket.setTimeout(8000, link.close);
        function selectProtocol(protocol) {
            if (link.ready) return;
            clearTimeout(link.probe);
            link.protocol = protocol;
            link.ready = true;
            flow.set("rotatorProtocol", protocol);
            node.status({fill:"green",shape:"dot",text:protocol === "pi" ? "Remote Pi bridge" : "Remote Hamlib"});
            link.send(cfg.query);
        }
        socket.on("connect", () => {
            socket.write("BUDDIHEX\n");
            link.probe = setTimeout(() => selectProtocol("hamlib"), 1200);
        });
        socket.on("error", error => node.status({fill:"red",shape:"ring",text:error.message}));
        socket.on("close", () => {
            clearTimeout(link.probe);
            if (globalThis.rotatorLink === link) {
                globalThis.rotatorLink = null;
                markOffline();
                node.status({fill:"yellow",shape:"ring",text:"Remote disconnected"});
            }
        });
        link.send = value => {
            if (link.protocol === "pi") socket.write(value + "\n");
            else if (value === cfg.query) socket.write(";p\n");
            else if (value === cfg.stop) socket.write(";S\n");
            else if (value.startsWith(cfg.setPrefix)) socket.write(";P " + Number(value.slice(cfg.setPrefix.length)) + " 0\n");
        };
        socket.on("data", data => {
            link.buffer += data;
            if (link.buffer.length > 32768) return link.close();
            let newline;
            while ((newline = link.buffer.indexOf("\n")) >= 0) {
                const line = link.buffer.slice(0,newline).trim();
                link.buffer = link.buffer.slice(newline+1);
                if (!line) continue;
                if (!link.ready) {
                    if (line === "BUDDIHEX 1") selectProtocol("pi");
                    else if (/^RPRT\s+-\d+$/.test(line)) selectProtocol("hamlib");
                    continue;
                }
                if (link.protocol === "pi") receive(line);
                else {
                    const azimuth = line.match(/(?:^|;)Azimuth:\s*(-?\d+(?:\.\d+)?)(?:;|$)/);
                    const report = line.match(/(?:^|;)RPRT\s+(-?\d+)$/);
                    const bearing = Number(azimuth?.[1]);
                    if (azimuth && report?.[1] === "0" && bearing >= 0 && bearing <= 360) receive("AZ:" + bearing);
                    else if (report && report[1] !== "0" && line.includes(";")) receive("ERR: Hamlib returned " + report[1]);
                }
            }
        });
    } else {
        node.error('Choose "direct", "remote", or "pi" in CONFIG.');
        return null;
    }
}
const link = globalThis.rotatorLink;
if (link.ready) link.send(command);
else if (command !== cfg.query) node.warn("Rotator connection is not ready; command discarded.");
return null;

const text = String(msg.payload || "").trim();
if (!/^(GET_BEARING:|AZ:|ERR:)/.test(text) && !/error/i.test(text)) return null;
let state = flow.get("rotatorState") || {};

state.lastReply = text;
state.lastSeen = Date.now();
state.online = true;
state.error = "";
state.stuck = false;

if (text.startsWith("GET_BEARING:")) {
    const parts = text.split(":");
    const bearing = Number(parts[1]);
    if (Number.isFinite(bearing)) state.bearing = bearing;

    if (parts.includes("CW")) state.direction = "CW";
    else if (parts.includes("CCW")) state.direction = "CCW";
    else state.direction = "STOP";

    state.stuck = parts.some(p => String(p).toLowerCase() === "stuck");
    if (bearing < 0 || parts.includes("Error!")) state.error = text;
}
else if (text.startsWith("AZ:")) {
    const bearing = parseFloat(text.substring(3));
    if (Number.isFinite(bearing)) state.bearing = bearing;
    state.direction = flow.get("rotatorProtocol") === "hamlib" ? "UNKNOWN" : state.direction;
}
else if (/error/i.test(text) || text.startsWith("ERR:")) {
    state.error = text;
}

let followUp = null;
const north = Number(state.bearing);
if (state.routingViaNorth && Number.isFinite(north) &&
    (north <= 3 || north >= 357) && state.direction === "STOP") {
    const finalTarget = Number(state.pendingTarget);
    const cfg = flow.get("rotatorConfig") || {};
    if (Number.isFinite(finalTarget) && cfg.setPrefix) {
        const finalCommand = cfg.setPrefix + String(Math.round(finalTarget) % 360);
        followUp = {
            payload: Buffer.from(finalCommand, "utf8"),
            ip: cfg.host,
            port: Number(cfg.commandPort)
        };
        state.lastCommand = finalCommand;
    }
    delete state.pendingTarget;
    state.routingViaNorth = false;
}

flow.set("rotatorState", state);
node.status({
    fill: state.stuck || state.error ? "red" : "green",
    shape: state.direction === "STOP" ? "ring" : "dot",
    text: (state.bearing ?? "?") + "° " + state.direction
});
msg.payload = state;
return [msg, followUp];

const cfg = flow.get("rotatorConfig");
if (!cfg) {
    node.error("Rotator configuration is not initialized", msg);
    return null;
}

const input = msg.payload || {};
const action = String(input.action || "").toLowerCase();
if (action === "clear-qrz") {
    flow.set("qrzTarget", null);
    flow.set("lookupID", null);
    return null;
}
if (action === "lookup") {
    const callsign = String(input.callsign || "").trim().toUpperCase();
    // A failed/new search must never leave an older QRZ target armed.
    flow.set("qrzTarget", null);
    flow.set("lookupID", msg._msgid);
    return [null, {topic:"qrz-login", lookupID:msg._msgid, payload:{callsign}}];
}

let commandText = "";
let target = null;
let state = flow.get("rotatorState") || {};

if (action === "set" || action === "set-qrz") {
    let bearing;
    if (action === "set-qrz") {
        const qrzTarget = flow.get("qrzTarget");
        const requestedCall = String(input.callsign || "").trim().toUpperCase();
        if (!qrzTarget || !Number.isFinite(Number(qrzTarget.bearing)) ||
            !requestedCall || requestedCall !== String(qrzTarget.callsign || "").toUpperCase()) {
            node.warn("QRZ target is missing or no longer matches the displayed callsign");
            return null;
        }
        bearing = Number(qrzTarget.bearing);
    } else {
        bearing = Number(input.bearing);
    }
    if (!Number.isFinite(bearing) || bearing < 0 || bearing > 360) {
        node.warn("Rejected invalid bearing: " + input.bearing);
        return null;
    }
    target = Math.round(bearing) % 360;

    // The permitted travel arc goes through north, never through/past south.
    // If current and requested bearings are on opposite sides of south, first
    // park at north and send the final target after the rotor reports STOP.
    const current = Number(state.bearing);
    const currentEast = Number.isFinite(current) && current > 0 && current < 180;
    const currentWest = Number.isFinite(current) && current > 180 && current < 360;
    const targetEast = target > 0 && target < 180;
    const targetWest = target > 180 && target < 360;
    const needsNorthRoute = (currentEast && targetWest) || (currentWest && targetEast);
    if (flow.get("rotatorProtocol") === "hamlib" && (!state.online || state.bearing == null || needsNorthRoute)) {
        return [{topic:"rotator-command-status", payload:{error:needsNorthRoute
            ? "Turn to north first in Hamlib mode, then select the final heading."
            : "Wait for a live Hamlib bearing before turning."}}, null];
    }

    state.target = target;
    if (needsNorthRoute) {
        state.pendingTarget = target;
        state.routingViaNorth = true;
        commandText = cfg.setPrefix + "0";
    } else {
        delete state.pendingTarget;
        state.routingViaNorth = false;
        commandText = cfg.setPrefix + String(target);
    }
}
else if (action === "stop") {
    commandText = cfg.stop;
    delete state.pendingTarget;
    state.routingViaNorth = false;
}
else if (action === "query") commandText = cfg.query;
else if (action === "calibrate") {
    if (cfg.connectionType === "remote" && flow.get("rotatorProtocol") !== "pi") {
        return [{topic:"rotator-command-status", payload:{error:"Set North requires a connected BuddiHex Pi bridge or a Direct connection."}}, null];
    }
    commandText = cfg.calibrate;
}
else {
    node.warn("Rejected unknown rotator action: " + action);
    return null;
}

state.lastCommand = commandText;
flow.set("rotatorState", state);

node.status({fill:"blue", shape:"dot", text:"TX " + commandText});
return [{
    payload: Buffer.from(commandText, "utf8"),
    ip: cfg.host,
    port: Number(cfg.commandPort)
}, null];

const cfg = flow.get("rotatorConfig") || {};
const callsign = String(msg.payload?.callsign || "").trim().toUpperCase();
const result = error => [null, {lookupID:msg.lookupID, payload:{error}}];
if (!/^[A-Z0-9]+(?:\/[A-Z0-9]+)*$/.test(callsign) || callsign.length > 15) {
    return result("Enter a valid callsign or prefix.");
}
if (!Number.isFinite(cfg.stationLat) || cfg.stationLat < -90 || cfg.stationLat > 90 ||
    !Number.isFinite(cfg.stationLon) || cfg.stationLon < -180 || cfg.stationLon > 180) {
    return result("Set valid stationLat and stationLon numbers in the CONFIG function.");
}
if (!cfg.qrzUsername || !cfg.qrzPassword) {
    return [null, null, {topic:"dxcc-fallback", callsign, lookupID:msg.lookupID,
        qrzFailure:"QRZ credentials are missing from CONFIG."}];
}
msg.callsign = callsign;
msg.url = "https://xmldata.qrz.com/xml/current/?" +
    "username=" + encodeURIComponent(cfg.qrzUsername) +
    "&password=" + encodeURIComponent(cfg.qrzPassword) +
    "&agent=NodeRED-BuddiHex-v1.1";
msg.method = "GET";
msg.requestTimeout = 15000;
delete msg.payload;
return [msg, null];

const fallback = error => ({topic:"dxcc-fallback", callsign:msg.callsign,
    lookupID:msg.lookupID, qrzFailure:error});
if (msg.statusCode && Number(msg.statusCode) !== 200) {
    return [null, fallback("QRZ login HTTP error: " + msg.statusCode)];
}
const xml = String(msg.payload || "");
const read = tag => {
    const match = xml.match(new RegExp("<(?:\\w+:)?" + tag + ">([\\s\\S]*?)<\\/(?:\\w+:)?" + tag + ">", "i"));
    return match ? match[1].replace(/&amp;/g,"&").replace(/&lt;/g,"<").replace(/&gt;/g,">").trim() : "";
};
const error = read("Error");
const key = read("Key");
if (!key) return [null, fallback(error || "QRZ login failed. Check credentials and XML access.")];

msg.url = "https://xmldata.qrz.com/xml/current/?s=" +
    encodeURIComponent(key) + "&callsign=" + encodeURIComponent(msg.callsign);
msg.method = "GET";
delete msg.payload;
delete msg.headers;
delete msg.statusCode;
delete msg.responseUrl;
return [msg, null];

const fallback = error => ({topic:"dxcc-fallback", callsign:msg.callsign,
    lookupID:msg.lookupID, qrzFailure:error});
if (msg.statusCode && Number(msg.statusCode) !== 200) {
    return fallback("QRZ lookup HTTP error: " + msg.statusCode);
}
const xml = String(msg.payload || "");
const read = tag => {
    const match = xml.match(new RegExp("<(?:\\w+:)?" + tag + ">([\\s\\S]*?)<\\/(?:\\w+:)?" + tag + ">", "i"));
    return match ? match[1].replace(/&amp;/g,"&").replace(/&lt;/g,"<").replace(/&gt;/g,">").trim() : "";
};
const apiError = read("Error");
if (apiError) return fallback(apiError);

// A successful HTTP response can still contain only a Session block. Do not
// fall through to locator parsing unless QRZ actually returned a Callsign.
const hasCallsignRecord = /<(?:\w+:)?Callsign(?:\s[^>]*)?>[\s\S]*?<\/(?:\w+:)?Callsign>/i.test(xml);
const returnedCall = read("call");
if (!hasCallsignRecord || !returnedCall) {
    return fallback("Callsign not found in QRZ.");
}

const latText = read("lat");
const lonText = read("lon");
let lat = latText ? Number(latText) : NaN;
let lon = lonText ? Number(lonText) : NaN;
const grid = read("grid").toUpperCase();

function maidenhead(locator) {
    const g = String(locator || "").toUpperCase();
    if (!/^[A-R]{2}[0-9]{2}([A-X]{2})?$/.test(g)) return null;
    let x = (g.charCodeAt(0)-65)*20 - 180 + Number(g[2])*2;
    let y = (g.charCodeAt(1)-65)*10 - 90 + Number(g[3]);
    let width = 2, height = 1;
    if (g.length >= 6) {
        x += (g.charCodeAt(4)-65) * (2/24);
        y += (g.charCodeAt(5)-65) * (1/24);
        width = 2/24; height = 1/24;
    }
    return {lat:y+height/2, lon:x+width/2};
}
if (!Number.isFinite(lat) || lat < -90 || lat > 90 ||
    !Number.isFinite(lon) || lon < -180 || lon > 180) {
    const point = maidenhead(grid);
    if (!point) return fallback(read("Message") || "QRZ returned no usable latitude/longitude or grid locator. Check QRZ XML subscription access.");
    lat = point.lat; lon = point.lon;
}

return {lookupID:msg.lookupID, payload:{
    call:returnedCall, name:read("name_fmt") || [read("fname"),read("name")].filter(Boolean).join(" "),
    grid, country:read("country") || read("land"), lat, lon, source:"QRZ"
}};

const fallback = error => ({topic:"dxcc-fallback", callsign:msg.callsign,
    lookupID:msg.lookupID, qrzFailure:error});
return fallback("QRZ connection failed or timed out.");

const input = msg.payload;
if (!input || typeof input !== "object" || Array.isArray(input)) return null;
const action = String(input.action || "").toLowerCase();
if (msg.topic === "dxcc-update" && action === "update-country-list") {
    return [null, null, {topic:"dxcc-update"}];
}
const known = ["lookup", "clear-qrz", "set", "set-qrz", "stop", "query", "calibrate"];
if (!["rotator-command", "qrz-lookup"].includes(msg.topic) || !known.includes(action)) return null;
const fail = error => [null, {topic:"rotator-command-status",payload:{error}}];
if (action === "calibrate") {
    const state = flow.get("rotatorState") || {};
    if (!state.online || !state.lastSeen || Date.now()-state.lastSeen > 6500 ||
        state.direction !== "STOP" || state.routingViaNorth || state.stuck || state.error) {
        return fail("North was not calibrated. Press STOP and wait for fresh, stopped rotor feedback. The antenna must already physically point true north.");
    }
}
if ((action === "set" && (input.bearing === null || input.bearing === undefined || String(input.bearing).trim() === "")) ||
    (action === "set" && (!Number.isFinite(Number(input.bearing)) || Number(input.bearing)<0 || Number(input.bearing)>360))) {
    return fail("Enter a target bearing from 0 to 360 degrees.");
}
if (action === "set-qrz") {
    const saved = flow.get("qrzTarget");
    if (!saved || !Number.isFinite(Number(saved.bearing)) ||
        String(saved.callsign || "").toUpperCase() !== String(input.callsign || "").toUpperCase()) {
        return fail("Look up the callsign again before pressing ROTATE TO. No movement was sent.");
    }
}
return [{topic:action === "lookup" ? "qrz-lookup" : "rotator-command", payload:Object.assign({},input)}, null];

if (!msg.payload || typeof msg.payload !== "object") return null;
// A new message removes any inherited QRZ topic or fields.
return {topic:"rotator-telemetry",payload:{rotator:{...JSON.parse(JSON.stringify(msg.payload)), rotatorProtocol:flow.get("rotatorProtocol") || null, connectionType:(flow.get("rotatorConfig") || {}).connectionType || "direct"}}};

if (msg.topic === "rotator-command-status") return msg;
const command = Buffer.isBuffer(msg.payload) ? msg.payload.toString("utf8") : String(msg.payload || "");
const cfg = flow.get("rotatorConfig") || {};
const state = flow.get("rotatorState") || {};
let message = "Command sent: " + command;
if (command === cfg.calibrate) message = "Set-current-position-as-north command sent. No rotation command was sent by this calibration action.";
else if (command.startsWith(cfg.setPrefix || "<AZIMUTH>")) {
    message += state.routingViaNorth ? " — north waypoint; final target " + state.pendingTarget + "° is queued." : " — awaiting rotor feedback.";
}
return {topic:"rotator-command-status",payload:{command,message}};

if (!msg.lookupID || msg.lookupID !== flow.get("lookupID") || !msg.payload) return null;
const cfg = flow.get("rotatorConfig") || {};
const result = msg.payload;
if (result.error) return {topic:"qrz-result", payload:result};
const {lat, lon} = result;
const rad = d => d * Math.PI / 180;
const lat1 = rad(cfg.stationLat), lat2 = rad(lat);
const dLon = rad(lon - cfg.stationLon);
const y = Math.sin(dLon) * Math.cos(lat2);
const x = Math.cos(lat1)*Math.sin(lat2) - Math.sin(lat1)*Math.cos(lat2)*Math.cos(dLon);
const bearing = Math.round((Math.atan2(y, x) * 180 / Math.PI + 360) % 360) % 360;
const dLat = lat2 - lat1;
const a = Math.max(0, Math.min(1, Math.sin(dLat/2)**2 + Math.cos(lat1)*Math.cos(lat2)*Math.sin(dLon/2)**2));
const distance = Math.round(6371 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a)));

flow.set("qrzTarget", {callsign:result.call, bearing, createdAt:Date.now()});
return {topic:"qrz-result", payload:{...result, bearing, distance}};

const fallback = msg.topic === "dxcc-fallback";
const refresh = msg.topic === "dxcc-update";
if (fallback && (!msg.lookupID || msg.lookupID !== flow.get("lookupID"))) return null;
const status = (message, updating = false) => ({topic:"dxcc-status", payload:{message, updating}});
const report = (request, payload) => ({lookupID:request.lookupID, payload});
const file = env.get("BUDDIHEX_DXCC_FILE") ||
    path.join(env.get("HOME") || ".", ".node-red", "buddihex-cty.dat");

function parse(data) {
    const text = Buffer.isBuffer(data) ? data.toString("latin1") : String(data ?? "");
    const records = text.split(";");
    if (records.pop().trim() || records.length < 300) throw Error("Incomplete CTY.DAT");
    const exact = Object.create(null);
    const prefixes = Object.create(null);
    let count = 0;
    const coordinate = (country, lat, west) => {
        if (!lat.trim() || !west.trim() || !(Math.abs(Number(lat)) <= 90) ||
            !(Math.abs(Number(west)) <= 180)) throw Error("Invalid CTY.DAT coordinates");
        return {country, lat:Number(lat), lon:-Number(west)};
    };
    for (const record of records) {
        const fields = record.split(":").map(field => field.trim());
        if (fields.length !== 9 || !fields[0] || !fields[7]) throw Error("Invalid CTY.DAT record");
        if (fields[7].startsWith("*")) continue;
        const location = coordinate(fields[0], fields[4], fields[5]);
        prefixes[fields[7].toUpperCase()] = location;
        count += 1;
        for (const entry of fields[8].split(",")) {
            const token = entry.trim().toUpperCase();
            const key = token.match(/^=?[A-Z0-9/]+/)?.[0];
            if (!key) throw Error("Invalid CTY.DAT prefix");
            const point = token.match(/<([^/<>]+)\/([^<>]+)>/);
            const target = point ? coordinate(location.country, point[1], point[2]) : location;
            if (key.startsWith("=")) exact[key.slice(1)] = target;
            else prefixes[key] = target;
        }
    }
    if (count < 300) throw Error("Incomplete DXCC list");
    return {exact, prefixes, count};
}

function resolve(request, list) {
    if (!request || request.lookupID !== flow.get("lookupID")) return null;
    const call = request.callsign;
    let match = list.exact[call];
    for (let length = call.length; !match && length > 0; length--) {
        match = list.prefixes[call.slice(0, length)];
    }
    return report(request, match
        ? {call, grid:"", name:"", source:"DXCC estimate", ...match}
        : {error:request.qrzFailure + " No DXCC match for " + call + "."});
}

if (fallback) {
    try {
        const cached = parse(fs.readFileSync(file));
        return [null, null, resolve(msg, cached)];
    } catch {
        context.set("waiting", {lookupID:msg.lookupID, callsign:msg.callsign, qrzFailure:msg.qrzFailure});
    }
}

if (refresh || fallback) {
    if (context.get("downloadID")) {
        return [null, status("Country list download in progress…", true), null];
    }
    context.set("downloadID", msg._msgid);
    return [{topic:"dxcc-download", downloadID:msg._msgid, method:"GET",
        url:"https://download.win-test.com/files/country/CTY.DAT", requestTimeout:15000},
        status("Downloading country list…", true), null];
}

if (msg.topic !== "dxcc-download" || !msg.downloadID ||
    msg.downloadID !== context.get("downloadID")) return null;
const waiting = context.get("waiting");
context.set("waiting", null);
context.set("downloadID", null);
let list;
let temp;
try {
    if (msg.error || Number(msg.statusCode) !== 200) throw Error("Download failed");
    list = parse(msg.payload);
    fs.mkdirSync(path.dirname(file), {recursive:true});
    temp = file + "." + msg.downloadID + ".tmp";
    fs.writeFileSync(temp, msg.payload, {flag:"wx"});
    fs.renameSync(temp, file);
    return [null, status("Updated " + list.count + " DXCC entities."), resolve(waiting, list)];
} catch (error) {
    if (temp) {
        try { fs.unlinkSync(temp); } catch {}
    }
    const detail = list ? "Could not save the country list. Check the cache directory permissions."
        : "Country list download failed or returned invalid data.";
    return [null, status(detail), list ? resolve(waiting, list) :
        (waiting ? report(waiting, {error:waiting.qrzFailure + " " + detail}) : null)];
}
